'use strict';
// A single club roster, with independent saved teams for every bout format.
function rosterFormat(){return [1,2,3,5].includes(UI.rosterFormat)?UI.rosterFormat:5}
function rosterMembers(){return [...new Set(G.lineups[rosterFormat()]||[])].filter(id=>G.beasts[id]?.clubId==='P'&&G.clubs.P.roster.includes(id)).slice(0,rosterFormat())}
function rosterStatus(b){return b.inj?`Injured · ${b.inj}d`:b.energy<50?'Low energy':b.fat>55?'Needs rest':rosterMembers().includes(b.id)?'First team':'Reserve'}
function rosterAbilityChips(b){const ab=SPECIES[b.sp].ab;return `<button class="ability-chip signature" data-act="profile" data-id="${b.id}" data-pt="skills" title="${esc(ABINFO[ab][0]+': '+ABINFO[ab][1])}" aria-label="${esc(b.name+' · '+ABINFO[ab][0])}">${esc(ABINFO[ab][0])}</button>${Object.keys(b.techniques||{}).filter(k=>TECHNIQUES[k]).map(k=>`<button class="ability-chip" data-act="profile" data-id="${b.id}" data-pt="skills" title="${esc(TECHNIQUES[k].n+': '+TECHNIQUES[k].d)}">${TECHNIQUES[k].icon} ${esc(TECHNIQUES[k].n)} ${b.techniques[k]}</button>`).join('')}${Object.keys(b.perks||{}).filter(k=>PERKS[k]).slice(0,4).map(k=>`<span class="power-dot" title="${esc(PERKS[k].n)} · ${b.perks[k]}">◆</span>`).join('')}`}
function rosterCard(b,index,bench=false){return `<article class="roster-starter ${bench?'reserve':''} ${b.inj?'injured':''} ${UI.rosterSwap&&!bench?'swap-target':''}"><button class="roster-model" data-act="${UI.rosterSwap&&!bench?'rosterReplace':'profile'}" data-id="${b.id}" aria-label="${UI.rosterSwap&&!bench?'Replace '+esc(b.name):'Open '+esc(b.name)}"><span class="roster-shirt">${bench?'RESERVE':String(index+1).padStart(2,'0')}</span>${beastArt(b.sp)}<strong>${esc(b.name)}</strong><small>${roleOf(b)} · Lv ${b.lvl}</small></button><div class="roster-energy" title="${b.energy} energy"><i style="width:${b.energy}%"></i></div><span class="roster-condition ${b.inj||b.energy<50?'bad':''}">${rosterStatus(b)}</span><div class="roster-card-actions"><button class="linkbtn" data-act="profile" data-id="${b.id}" data-pt="tactics">Tactics</button><button class="linkbtn" data-act="${bench?'rosterField':'rosterBench'}" data-id="${b.id}" ${bench&&b.inj?'disabled':''}>${bench?'Field':'Bench'}</button></div></article>`}
function rosterSortValue(b,key){const stats=combatStats(b);return ({name:b.name,role:roleOf(b),ovr:ovr(b),lvl:b.lvl,hp:stats.hp,atk:stats.atk,def:stats.def,speed:stats.mv,imp:b.season.imp/(b.season.m||1),kda:(b.season.k+b.season.a)/Math.max(1,b.season.d),bouts:b.season.m,energy:b.energy,value:value(b),age:b.age})[key]??ovr(b)}
function rosterSorted(){let heroes=clubBeasts().filter(b=>!UI.rosterRole||UI.rosterRole==='all'||ROLE_LINE[roleOf(b)]===UI.rosterRole);const key=UI.rosterSort||'ovr',direction=UI.rosterAsc?1:-1;return heroes.sort((a,b)=>{const x=rosterSortValue(a,key),y=rosterSortValue(b,key);return (typeof x==='string'?x.localeCompare(y):x-y)*direction||a.name.localeCompare(b.name)})}
function rosterColumn(key,label){const on=(UI.rosterSort||'ovr')===key;return `<th scope="col" ${on?`aria-sort="${UI.rosterAsc?'ascending':'descending'}"`:''}><button data-act="rosterSort" data-k="${key}">${label}${on?UI.rosterAsc?' ↑':' ↓':''}</button></th>`}
function rosterComparison(){const heroes=(UI.rosterCompare||[]).map(id=>G.beasts[id]).filter(b=>b?.clubId==='P');if(heroes.length!==2)return '';const [a,b]=heroes,ca=combatStats(a),cb=combatStats(b);return `<section class="panel roster-compare"><div class="row between"><div><span class="lbl gold">SIDE BY SIDE</span><h3>${esc(a.name)} <span class="dust">&</span> ${esc(b.name)}</h3></div><button class="btn sm" data-act="rosterCompareClear">Clear comparison</button></div><div class="compare-metrics">${[['Health',ca.hp,cb.hp],['Attack',ca.atk,cb.atk],['Defense',ca.def,cb.def],['Speed',ca.mv,cb.mv],['Energy',a.energy,b.energy],['Impact / bout',a.season.imp/(a.season.m||1),b.season.imp/(b.season.m||1)]].map(([n,x,y])=>`<div><b class="${x>y?'gold':''}">${x.toFixed(1)}</b><span>${n}</span><b class="${y>x?'gold':''}">${y.toFixed(1)}</b></div>`).join('')}</div><p class="note">Current combat stats include energy, injuries, and learned powers. Impact is measured from completed arena bouts.</p></section>`}
viewRoster=function(){
 const heroes=clubBeasts(),members=rosterMembers(),bench=heroes.filter(b=>!members.includes(b.id)),size=rosterFormat(),combat=UI.rosterView==='combat',selected=G.beasts[UI.rosterSwap],compare=UI.rosterCompare||[];
 return `<div class="roster-heading"><div><span class="lbl gold">${esc(G.name)} · PERSONNEL</span><h2>The first team.</h2><p>${heroes.length} / 12 heroes · ${playerUpkeep()} gold upkeep per matchday · ${heroes.filter(b=>!b.inj).length} available</p></div><button class="btn" data-act="tab" data-k="market">Recruit heroes →</button></div><section class="panel roster-lineup"><div class="row between"><div><span class="lbl">SAVED LINEUP</span><h3>${size}v${size} <span class="dust">· ${members.length} / ${size} selected</span></h3></div><div class="seg" aria-label="Saved lineup size">${[1,2,3,5].map(n=>`<button class="${size===n?'on':''}" data-act="rosterFormat" data-n="${n}">${n}v${n}${n===5?' League':''}</button>`).join('')}</div></div>${selected?`<div class="roster-swap-note"><span>Choose a starter above to replace with <b>${esc(selected.name)}</b>.</span><button class="linkbtn" data-act="rosterCancel">Cancel swap</button></div>`:''}<div class="roster-starters">${members.map((id,i)=>rosterCard(G.beasts[id],i)).join('')}${Array.from({length:size-members.length},(_,i)=>`<div class="roster-vacancy"><span>${String(members.length+i+1).padStart(2,'0')}</span><b>Open place</b><small>${bench.length?'Field a reserve below':'Recruit in the Market'}</small></div>`).join('')}</div><div class="roster-lineup-footer"><p>Saved automatically. Choose your formation on the match preparation screen.</p><button class="btn sm" data-act="rosterSuggest" ${heroes.length?'':'disabled'}>Suggest fit heroes</button><button class="linkbtn" data-act="rosterClear" ${members.length?'':'disabled'}>Clear lineup</button></div></section><section class="roster-reserves"><div class="row between"><h3>Reserves <span class="dust">· ${bench.length}</span></h3><span class="note">Bench time restores energy. Arena appearances earn XP.</span></div><div class="roster-bench">${bench.map((b,i)=>rosterCard(b,i,true)).join('')||'<p class="empty">Every hero has a place. Recruit another to build depth.</p>'}</div></section><section class="panel roster-register"><div class="row between"><div><span class="lbl gold">THE ROSTER REGISTER</span><h3>Every hero. Every detail.</h3></div><div class="seg" aria-label="Roster view"><button class="${combat?'':'on'}" data-act="rosterView" data-k="growth">Development</button><button class="${combat?'on':''}" data-act="rosterView" data-k="combat">Combat stats</button></div></div><div class="roster-tools"><div class="seg" aria-label="Role filter">${[['all','All roles'],['front','Frontline'],['flank','Flank'],['back','Backline']].map(([k,n])=>`<button class="${(UI.rosterRole||'all')===k?'on':''}" data-act="rosterRole" data-k="${k}">${n}</button>`).join('')}</div><span class="note">Select two heroes to compare · ${compare.length} / 2</span></div><div class="tw"><table class="roster-table"><thead><tr><th scope="col">Compare</th>${rosterColumn('name','Hero')}${rosterColumn('lvl','LV')}${rosterColumn('ovr','OVR')}${combat?rosterColumn('hp','HP')+rosterColumn('atk','ATK')+rosterColumn('def','DEF')+rosterColumn('speed','SPD'):'<th scope="col">Next level</th><th scope="col">Growth focus</th>'}${rosterColumn('imp','Impact / bout')}${rosterColumn('bouts','Bouts')}${rosterColumn('energy','Energy')}<th scope="col">Status</th><th scope="col">Actions</th></tr></thead><tbody>${rosterSorted().map(b=>{const stats=combatStats(b);return `<tr class="${members.includes(b.id)?'first-team':''} ${compare.includes(b.id)?'comparing':''}"><td><button class="compare-check ${compare.includes(b.id)?'checked':''}" data-act="rosterCompare" data-id="${b.id}" aria-label="Compare ${esc(b.name)}" aria-pressed="${compare.includes(b.id)}">${compare.includes(b.id)?'✓':'+'}</button></td><th scope="row"><div class="roster-identity"><button class="roster-mini" data-act="profile" data-id="${b.id}" aria-label="Open ${esc(b.name)}">${beastArt(b.sp)}</button><div><button class="hero-name" data-act="profile" data-id="${b.id}">${esc(b.name)}</button><small>${SPECIES[b.sp].n} · ${roleOf(b)}</small><div class="roster-abilities">${rosterAbilityChips(b)}</div></div></div></th><td>${b.lvl}</td><td class="gold">${ovr(b)}</td>${combat?`<td>${fmt(stats.hp)}</td><td>${stats.atk.toFixed(1)}</td><td>${fmt(stats.def)}</td><td>${fmt(stats.mv)}</td>`:`<td><span class="roster-xp"><i style="width:${clamp(b.xp/xpNeed(b.lvl)*100,0,100)}%"></i></span><small>${b.lvl>=lvlCap(b)?'Level cap':`${b.xp} / ${xpNeed(b.lvl)} XP`}</small><small class="gold">${potRange(b)} potential</small></td><td><select data-chg="focus" data-id="${b.id}" aria-label="${esc(b.name)} growth focus">${Object.keys(FOCUS).map(k=>`<option ${k===b.focus?'selected':''}>${k}</option>`).join('')}</select></td>`}<td>${b.season.m?(b.season.imp/b.season.m).toFixed(1):'<span class="mute">—</span>'}</td><td>${b.season.m}</td><td><b class="${b.energy<50?'bad':''}">${b.energy}%</b><small>${b.fat||0} fatigue</small></td><td><span class="roster-status ${b.inj?'injured':members.includes(b.id)?'first':''}">${rosterStatus(b)}</span></td><td><div class="roster-row-actions"><button class="btn sm" data-act="${members.includes(b.id)?'rosterBench':'rosterField'}" data-id="${b.id}" ${b.inj&&!members.includes(b.id)?'disabled':''}>${members.includes(b.id)?'Bench':b.inj?'Recovering':members.length>=size?'Swap in':'Field'}</button><button class="linkbtn" data-act="profile" data-id="${b.id}" data-pt="tactics">Tactics</button></div></td></tr>`}).join('')||'<tr><td colspan="13" class="empty">No heroes in this group. Recruit from the Market.</td></tr>'}</tbody></table></div><p class="roster-growth-note">Growth focus shapes future level-ups. Skill choices appear only when that hero levels up after an arena bout; victories slightly improve their rarity.</p></section>${rosterComparison()}<footer class="desk-actionbar"><span>${members.length} / ${size} in this saved team</span><button class="btn pri" data-act="${foundingOpen()?'tab':'next'}" ${foundingOpen()?'data-k="market"':''}>${foundingOpen()?'Complete recruitment':'Prepare next match'} →</button><span>Changes autosaved</span></footer>`;
};
function canEditRoster(){return !!G&&UI.mode==='hub'&&UI.tab==='roster'}
function saveRosterTeam(ids){G.lineups[rosterFormat()]=[...new Set(ids)].filter(id=>G.beasts[id]?.clubId==='P').slice(0,rosterFormat());if(UI.ctx&&!UI.ctx.draft&&lineupCapacity()===rosterFormat()){UI.sel=G.lineups[rosterFormat()].slice();normalizeFormation()}save();render()}
ACT.rosterFormat=d=>{const n=Number(d.n);if(![1,2,3,5].includes(n))return;UI.rosterFormat=n;UI.rosterSwap=null;render()};
ACT.rosterBench=d=>{if(!canEditRoster())return;UI.rosterSwap=null;saveRosterTeam(rosterMembers().filter(id=>id!==d.id))};
ACT.rosterField=d=>{const b=G?.beasts[d.id];if(!canEditRoster()||b?.clubId!=='P'||b.inj||rosterMembers().includes(d.id))return;const members=rosterMembers();if(members.length>=rosterFormat()){UI.rosterSwap=d.id;render();window.scrollTo({top:0,behavior:PREFS.motion?'smooth':'auto'});return}UI.rosterSwap=null;saveRosterTeam([...members,d.id])};
ACT.rosterReplace=d=>{const members=rosterMembers(),b=G?.beasts[UI.rosterSwap];if(!canEditRoster()||b?.clubId!=='P'||b.inj||!members.includes(d.id)||members.includes(b.id))return;UI.rosterSwap=null;saveRosterTeam(members.map(id=>id===d.id?b.id:id))};
ACT.rosterSuggest=()=>{if(!canEditRoster())return;UI.rosterSwap=null;saveRosterTeam(pickLineup('P',rosterFormat()).filter(b=>!b.inj).map(b=>b.id))};
ACT.rosterClear=()=>{if(!canEditRoster())return;UI.rosterSwap=null;saveRosterTeam([])};
ACT.rosterCancel=()=>{UI.rosterSwap=null;render()};
ACT.rosterSort=d=>{if(!['name','role','ovr','lvl','hp','atk','def','speed','imp','kda','bouts','energy','value','age'].includes(d.k))return;UI.rosterAsc=(UI.rosterSort||'ovr')===d.k?!UI.rosterAsc:d.k==='name'||d.k==='age';UI.rosterSort=d.k;render()};
ACT.rosterView=d=>{if(['combat','growth'].includes(d.k)){UI.rosterView=d.k;render()}};
ACT.rosterRole=d=>{if(['all','front','flank','back'].includes(d.k)){UI.rosterRole=d.k;render()}};
ACT.rosterCompare=d=>{if(G?.beasts[d.id]?.clubId!=='P')return;const ids=(UI.rosterCompare||[]).filter(id=>G.beasts[id]?.clubId==='P');if(ids.includes(d.id))UI.rosterCompare=ids.filter(id=>id!==d.id);else if(ids.length<2)UI.rosterCompare=[...ids,d.id];else{toast('Clear one comparison first.');return}render()};
ACT.rosterCompareClear=()=>{UI.rosterCompare=[];render()};
const rosterReset=resetRunUI;resetRunUI=function(){rosterReset();UI.rosterFormat=5;UI.rosterCompare=[];UI.rosterSwap=null;UI.rosterRole='all';UI.rosterSort='ovr';UI.rosterAsc=false};
